class Box:
 def run(self,x,y=2):return x,y
def change():
 Box.run.__defaults__=(9,)
 return 3
print(Box().run(change()))

class Box:
 def run(self,/,a=2):return a
method=Box().run
print(method(),method(4))
try:method(self=2)
except TypeError:print('keyword')

